import re, sys
chunk = [222,228,230,239,248,249,252,253,257,258,259,261,262,263,270,274,275,280,304,305,316,318,324,326,329,331,339,340,341,343,347]
out = []
for path in sys.argv[1:]:
    for ln in open(path).read().split('\n'):
        m = re.match(r'^- ([FP]-\d+) ', ln)
        owner = m.group(1) if m else '(line)'
        inchunk = owner.startswith('F-') and int(owner[2:]) in chunk
        if inchunk:
            continue
        for s in re.split(r'(?<=[.;])\s+', ln):
            for n in chunk:
                if re.search(r'F-%d(?!\d)' % n, s):
                    out.append((n, '%s %s: %s' % (path.split('/')[-1], owner, s[:260])))
for n, t in sorted(out):
    print('F-%d <- %s' % (n, t))

